  ('user_cust_1', 'Aarav Sharma', 'aarav.sharma@adishankara.ac.in', 'customer', 'Junior studying Economics. Always looking for unique dorm decor and thoughtful gifts for friends.', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80', 'Adi Shankara Institute of Engineering and Technology (ASIET)', true, array['Gift Hunting', 'Art Collector']),
  ('maker_ananya', 'Ananya Crafts', 'ananya.k@adishankara.ac.in', 'maker', 'Turning ideas into handmade yarn memories. Specializing in timeless crochet bouquets, dorm amigurumi, and custom floral arrangements that never wilt.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&q=80', 'ASIET Art & Design', true, array['Crochet', 'Handmade', 'Gift Wrapping', 'Botanical Crafts']),
  ('maker_claire', 'Claire Studio', 'claire.designs@adishankara.ac.in', 'maker', 'Handcrafted freshwater pearl jewelry, beaded personalized charms, and wire-wrapped crystal keepsakes crafted on the ASIET campus.', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=400&q=80', 'ASIET Materials Engineering', true, array['Jewelry Design', 'Pearl Threading', 'Wire Wrapping', 'Custom Engraving']),
  ('maker_dev', 'Dev Atelier', 'dev.paintings@adishankara.ac.in', 'maker', 'Fine arts sophomore capturing campus sunsets, personalized architectural watercolors, and mini desktop canvases.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'ASIET Arts & Humanities', true, array['Oil Painting', 'Watercolor', 'Campus Landscapes', 'Portraits']),
  ('maker_botanica', 'Botanica Dorm', 'botanica@adishankara.ac.in', 'maker', 'Small-batch botanical soy wax candles infused with campus garden scents, pressed flowers, and lavender notes.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&q=80', 'ASIET Environmental Science', true, array['Soy Candle Pouring', 'Aromatherapy', 'Pressed Florals']),
  ('maker_kavya', 'Kavya Pixels', 'kavya.pixels@adishankara.ac.in', 'maker', 'CS + Design double major creating whimsical digital portraits, cute stickers, and custom college event posters in 24 hours.', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=400&q=80', 'ASIET Computer Science & Design', true, array['Digital Illustration', 'Vector Art', 'Sticker Packs', 'Portraits'])
