  ('prod_4', 'maker_dev', 'Dev Atelier', 4.9, true, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'Mini Sunset Campus Canvas', 'An original 6x6-inch textured acrylic painting depicting golden hour over the campus quad. Comes with a matching wooden desktop easel and protective varnish finish.', 650, 'Art', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCTSkrHntrlxk6ZpItlN7G2bvKE4MYRMWLrH_TzwwQDz5jTjSgYYwaE7M5ffom2ksUZDd57sgSZCN7VUdOwlhAoaDmKCrdXL2YaBfDAxnrGnEzMAq75yrn5UDuLi96RAzSNzlSlPHRp2Mb1MFPDCpeShNTTbiE5e1xI8fdz0WBBla3mGKilRz2-DmT81gg_KWlwU9mt6vrgv3NTq4UuzsC_3iVhp7Zh6OA98ltNPqUU0AV7VMEmqeY', 3, true),
  ('prod_5', 'maker_claire', 'Claire Studio', 4.9, true, 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=400&q=80', 'Customized Friendship Bracelet Set', 'Set of two intricately hand-woven macrame friendship bracelets with waterproof waxed cords and stainless steel letter beads of your choice.', 199, 'Handmade', 'https://images.unsplash.com/photo-1611591475870-76c243f72166?auto=format&fit=crop&w=600&q=80', 15, true),
  ('prod_6', 'maker_ananya', 'Ananya Crafts', 4.8, true, 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&q=80', 'Custom Birthday Explosion Box', 'Handcrafted layered origami box that cascades open into photo slots, heartfelt quotes, and a miniature sweet treat compartment in the center. Perfect surprise birthday gift.', 499, 'Gifts', 'https://images.unsplash.com/photo-1549465220-1a8b9238cd48?auto=format&fit=crop&w=600&q=80', 5, true),
  ('prod_7', 'maker_kavya', 'Kavya Pixels', 4.9, true, 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=400&q=80', 'Digital Campus Portrait & Chibi', 'High-res hand-drawn digital cartoon portrait of you and your best friend or pet! Delivered within 24 hours as 300DPI print-ready PDF and transparent PNGs.', 249, 'Digital', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=600&q=80', 20, true)
